#include <stdio.h>
#include <stdlib.h>

int main() {
    for (int i = 0; i < 5; i++) {
        int *buffer = malloc(100 * sizeof(int));
        buffer[0] = i;
        printf("%d\n", buffer[0]);
        free(buffer);
    }
    return 0;
}
